*,:after,:before{
    box-sizing:inherit
}
body{
    font-family:Roboto,sans-serif;
    font-style:normal;
    font-weight:400
}
button,input,select,textarea{
    font-family:inherit
}
input[type=number]::-webkit-inner-spin-button,input[type=number]::-webkit-outer-spin-button{
    -webkit-appearance:none;
    margin:0
}
img{
    box-sizing:content-box
}
.pageRoot{
    background-color:#e6e4e1;
    position:absolute;
    left:0;
    top:0;
    bottom:0;
    right:0;
    transition:-webkit-transform .25s;
    transition:transform .25s;
    transition:transform .25s,-webkit-transform .25s
}
.show-side-menu .pageRoot{
    -webkit-transform:translateX(-200px);
    transform:translateX(-200px)
}
#messagingClientRoot,.messagingClientRoot{
    position:absolute;
    bottom:0;
    top:57px;
    width:100%;
    left:0;
    right:0
}
@media screen and (min-width:1280px){
    #messagingClientRoot,.messagingClientRoot{
        left:50%;
        margin:0 auto 0 -640px;
        width:1280px
    }
}
.pageBody{
    z-index:50;
    position:absolute;
    left:0;
    top:0;
    width:100%;
    min-height:100%;
    font-family:Arial,sans-serif;
    color:#333
}
#alert,#modal{
    position:absolute;
    z-index:3000060;
    width:0;
    height:0;
    overflow:visible
}
#alert{
    z-index:3000061
}
#sideMenu{
    z-index:-1;
    position:fixed;
    top:0;
    right:0;
    bottom:0;
    display:none
}
.show-side-menu #sideMenu{
    display:block
}
.mp-Toggle-label p a{
    display:inline
}
.mp-sdk-svg{
    display:block;
    background-size:auto 100%;
    background-repeat:no-repeat;
    height:100%;
    width:100%
}
